SELECT clientes.nombre, pedidos.producto
FROM pedidos
JOIN clientes ON pedidos.cliente_id = clientes.id;

ejemplo_resuelto.codigo:
SELECT producto, monto
FROM pedidos
WHERE monto > (SELECT AVG(monto) FROM pedidos);

solucion_paso_a_paso.codigo:
SELECT cliente_id, SUM(monto) as total
FROM pedidos
GROUP BY cliente_id
HAVING total > (
    SELECT AVG(total) FROM (
        SELECT SUM(monto) as total FROM pedidos GROUP BY cliente_id
    )
);

WITH gastos AS (
    SELECT cliente_id, SUM(monto) as total FROM pedidos GROUP BY cliente_id
)
SELECT cliente_id, total FROM gastos WHERE total > 900;
